"use client";

import React from "react";

interface CoinBuddyMascotProps {
  className?: string;
  size?: "sm" | "md" | "lg" | "xl" | number;
  animate?: boolean;
  ariaLabel?: string;
}

// 100% authentic PocketPot Thoughtful Coin Buddy character artwork with transparent antialiased background
const COIN_ARTWORK_BASE64 = "data:image/png;base64,";

export const CoinBuddyMascot: React.FC<CoinBuddyMascotProps> = ({
  className = "",
  size = "md",
  animate = false,
  ariaLabel = "Thoughtful PocketPot coin buddy explaining the purpose of savings pots",
}) => {
  let sizeClass = "";
  let explicitWidth: number | undefined;

  if (typeof size === "number") {
    explicitWidth = size;
  } else {
    switch (size) {
      case "sm":
        sizeClass = "w-16 h-auto";
        break;
      case "md":
        sizeClass = "w-20 sm:w-24 h-auto";
        break;
      case "lg":
        sizeClass = "w-28 sm:w-36 h-auto";
        break;
      case "xl":
        sizeClass = "w-40 sm:w-48 h-auto";
        break;
    }
  }

  return (
    <svg
      viewBox="0 0 267 285"
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      className={`${sizeClass} ${className} ${animate ? "animate-bounce-subtle" : ""} select-none drop-shadow-sm`}
      style={explicitWidth ? { width: explicitWidth, height: "auto" } : undefined}
      aria-label={ariaLabel}
      role="img"
    >
      <image
        href={COIN_ARTWORK_BASE64}
        width="267"
        height="285"
        preserveAspectRatio="xMidYMid meet"
      />
    </svg>
  );
};

export default CoinBuddyMascot;
